	@Test
	void childInvocationsShareOneChargeUntilTheLastPreparationCloses() {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = memory;
		try (NativeExecutionContext root = new NativeExecutionContext();
				NativeExecutionContext first = new NativeExecutionContext(root, EmptyBindingSet.getInstance());
				NativeExecutionContext second = new NativeExecutionContext(root, EmptyBindingSet.getInstance())) {
			Object recipe = new Object();
			NativeRecipeMemory.Lease firstLease = NativeRecipeMemory.retain(recipe, 4096L, first);
			assertNotNull(firstLease);
			long oneRecipe = memory.usedBytes();
			assertTrue(oneRecipe >= 4096L);
			NativeRecipeMemory.Lease secondLease = NativeRecipeMemory.retain(recipe, 4096L, second);
			assertNotNull(secondLease);
			assertEquals(oneRecipe, memory.usedBytes(), "a child invocation borrows the existing immutable graph");
			try {
				firstLease.close();
				first.close();
				assertEquals(oneRecipe, memory.usedBytes(), "closing one child cannot release another child's recipe");
				secondLease.close();
				assertEquals(0L, memory.usedBytes(), "the final preparation removes its directory entry and claim");
				try (NativeRecipeMemory.Lease rebound = NativeRecipeMemory.retain(recipe, 4096L, second)) {
					assertNotNull(rebound, "the same prepared artifact can be admitted again after the last close");
					assertEquals(oneRecipe, memory.usedBytes());
				}
				assertEquals(0L, memory.usedBytes());
			} finally {
				firstLease.close();
				secondLease.close();
			}
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
		assertEquals(0L, memory.usedBytes());
	}

