	@Test
	void bindingWaitsForTheCompleteCatalogAndChargesConstantsAddedBySiblingCompilation() {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager memory = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = memory;
		PlanValueCatalog.Builder builder = PlanValueCatalog.Builder.compiledTree();
		try (NativeExecutionContext execution = new NativeExecutionContext();
				LmdbFusedSipFactorizedRuntime.Session session = LmdbFusedSipFactorizedRuntime.create(693L, 1L << 16,
						false);
				NativePhysicalPreparation preparation = NativePhysicalPreparation.tryCreate(session)) {
			assertNotNull(preparation);
			NativeCompiledResultRecipe recipe;
			try (NativeRecipeMemory.Capture capture = new NativeRecipeMemory.Capture(builder)) {
				capture.reserve(128L);
				recipe = capture.finish(new TestRecipe(true, false), builder.build());
			}
			NativeResultBinding binding = binding(execution, session, preparation);
			long before = memory.usedBytes();
			assertNull(recipe.bind(binding), "a mutable catalog can grow after a premature binding's charge");
			assertEquals(before, memory.usedBytes());
			builder.internConstant(SimpleValueFactory.getInstance().createLiteral("x".repeat(4096)));
			builder.freeze();
			assertNotNull(recipe.bind(binding));
			assertTrue(memory.usedBytes() >= before + 4096L,
					"the final catalog includes constants added after this child recipe was captured");
		} finally {
			builder.abort();
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
		assertEquals(0L, memory.usedBytes());
	}

